-- DENTALCARE SWP391 — CANONICAL DEMO V2 SEED (synthetic clinical data)
-- Source: user-provided schema standalone + 2026-11-01/19 JSON blueprint.
-- ONLY fresh, dedicated database: DentalCare_SWP391_DEMO_V2_TEST
-- Account PasswordHash uses optional SESSION_CONTEXT('DentalCareDemoPasswordHash');
-- values are NULL when context is absent, until provisioned through the application's
-- existing ASP.NET-compatible password provisioning mechanism. NO shared credentials here.
-- Historical clinical/financial rows are FIXTURES, NOT real browser E2E evidence.
-- Imaging FileUrl paths are PLACEHOLDERS, NOT valid uploaded medical imaging.
-- Never run on production or the original UAT fixture DB.
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET DATEFORMAT ymd;
IF DB_NAME() IN (N'master', N'model', N'msdb', N'tempdb', N'DentalCare_SWP391', N'DentalCare_SWP391_Refactor_UAT', N'DentalCare_SWP391_UAT_Fixture_TEST')
  THROW 51000, 'DENIED: Refusing to seed protected or system databases.', 1;
IF (SELECT COUNT(*) FROM sys.tables WHERE is_ms_shipped = 0) <> 38
  THROW 51001, 'DENIED: Expected exactly 38 canonical schema tables.', 1;
IF NOT EXISTS (SELECT 1 FROM sys.tables WHERE name = 'AppointmentServices' AND schema_id = SCHEMA_ID('dbo'))
  THROW 51002, 'DENIED: expected unified AppointmentServices schema.', 1;
-- Second execution is intentionally a VERIFY-ONLY NO-OP. We never reset data or replay historical invoices.
IF EXISTS (SELECT 1 FROM dbo.ClinicProfile WHERE ClinicId = 1 AND Description LIKE N'%[[]DEMO-V2-SNAPSHOT]%')
BEGIN
  IF (SELECT COUNT(*) FROM dbo.Departments) <> 3 OR (SELECT COUNT(*) FROM dbo.DentistProfiles) <> 6
     OR (SELECT COUNT(*) FROM dbo.PatientProfiles) <> 32 OR (SELECT COUNT(*) FROM dbo.Appointments) <> 62
     OR (SELECT COUNT(*) FROM dbo.DepartmentServices) <> 12
     THROW 51003, 'Existing DEMO V2 seed has unexpected counts. Refusing to silently repair or reset.', 1;
  PRINT 'DEMO V2 snapshot already provisioned. Verification successful; no rows updated.';
  RETURN;
END;
IF EXISTS (SELECT 1 FROM dbo.UserAccounts) OR EXISTS(SELECT 1 FROM dbo.Appointments)
   OR EXISTS (SELECT 1 FROM dbo.ClinicProfile)
  THROW 51004, 'DENIED: seed requires pristine, otherwise empty canonical schema.', 1;
BEGIN TRY
  BEGIN TRANSACTION;

DECLARE @DemoPasswordHash varchar(255) = TRY_CONVERT(varchar(255), SESSION_CONTEXT(N'DentalCareDemoPasswordHash'));
IF @DemoPasswordHash IS NULL PRINT 'WARNING: demo logins disabled until password hashes are provisioned by an application-compatible hasher.';
