DECLARE @cat_blog INT=(SELECT CategoryId FROM dbo.BlogCategories WHERE Slug='kien-thuc-demo'), @cat_news INT=(SELECT CategoryId FROM dbo.BlogCategories WHERE Slug='tin-tuc-demo');
