INSERT dbo.BlogPosts(CategoryId,AuthorUserId,Title,Slug,Content,ReadTimeMinutes,PostType,Status,ApprovedByUserId,ApprovedAt,PublishedAt,CreatedAt) VALUES (@cat_news,@uid_ADMIN01,N'Tin tức phòng khám thử nghiệm','demo-tin-phong-kham',N'<p>Tin tức demo.</p>',2,'ClinicNews','Published',@uid_ADMIN01,'2026-11-15','2026-11-15','2026-11-14');
-- Transactional, DB-side assertions. A mismatch rolls back ALL seed data.
IF (SELECT COUNT(*) FROM dbo.Departments)<>3 THROW 51101,'Departments count mismatch',1;
IF (SELECT COUNT(*) FROM dbo.DentistProfiles)<>6 THROW 51102,'Dentists count mismatch',1;
IF (SELECT COUNT(*) FROM dbo.PatientProfiles)<>32 THROW 51103,'Patients count mismatch',1;
IF (SELECT COUNT(*) FROM dbo.DepartmentServices)<>12 THROW 51104,'Service count mismatch',1;
IF (SELECT COUNT(*) FROM dbo.Rooms)<>3 THROW 51105,'Room count mismatch',1;
IF (SELECT COUNT(*) FROM dbo.Medicines)<>9 THROW 51106,'Medicine count mismatch',1;
IF (SELECT COUNT(*) FROM dbo.Appointments)<>62 THROW 51107,'Appointment count mismatch',1;
IF (SELECT COUNT(*) FROM dbo.TreatmentPlans)<>5 THROW 51108,'TreatmentPlan count mismatch',1;
IF (SELECT COUNT(*) FROM dbo.Diagnostics)<>16 THROW 51109,'Diagnostics count mismatch',1;
IF (SELECT COUNT(*) FROM dbo.Invoices)<>48 THROW 51110,'Invoices count mismatch',1;
IF EXISTS (SELECT 1 FROM dbo.InvoiceItems ii JOIN dbo.Invoices inv ON inv.InvoiceId=ii.InvoiceId GROUP BY ii.InvoiceId,inv.TotalAmount HAVING SUM(ii.Quantity*ii.UnitPrice)<>inv.TotalAmount) THROW 51111,'Invoice line total mismatch',1;
IF EXISTS (SELECT 1 FROM dbo.Invoices inv LEFT JOIN (SELECT InvoiceId,SUM(Amount) AS amt FROM dbo.Payments WHERE Status='Successful' GROUP BY InvoiceId) p ON p.InvoiceId=inv.InvoiceId WHERE (inv.Status='Paid' AND ISNULL(p.amt,0)<>inv.FinalAmount) OR (inv.Status='Unpaid' AND ISNULL(p.amt,0)<>0) OR (inv.Status='PartiallyPaid' AND (ISNULL(p.amt,0)<=0 OR ISNULL(p.amt,0)>=inv.FinalAmount))) THROW 51112,'Invoice payment status mismatch',1;
IF EXISTS (SELECT 1 FROM dbo.AppointmentServices a JOIN dbo.DepartmentServices s ON a.DepartmentServiceId=s.DepartmentServiceId JOIN dbo.DentistProfiles d ON a.AssignedDentistUserId=d.UserId LEFT JOIN dbo.Rooms r ON r.RoomId=a.RoomId WHERE a.DepartmentId<>s.DepartmentId OR a.DepartmentId<>d.DepartmentId OR a.DepartmentId<>r.DepartmentId) THROW 51113,'Cross department mismatch',1;
IF EXISTS (SELECT 1 FROM dbo.AppointmentServices a JOIN dbo.PerformedServices p ON a.AppointmentServiceId=p.AppointmentServiceId WHERE a.Status<>'Completed') THROW 51114,'Billed unfinished service',1;
IF EXISTS (SELECT 1 FROM dbo.Medicines WHERE StockQuantity<0) THROW 51115,'Negative medicine stock',1;
COMMIT TRANSACTION;
PRINT 'SEED INSERT TRANSACTION COMMITTED — synthetic data only.';
SELECT 'Departments' ObjectName, COUNT(*) [RowCount] FROM dbo.Departments
UNION ALL SELECT 'DentistProfiles',COUNT(*) FROM dbo.DentistProfiles
UNION ALL SELECT 'PatientProfiles',COUNT(*) FROM dbo.PatientProfiles
UNION ALL SELECT 'Appointments',COUNT(*) FROM dbo.Appointments
UNION ALL SELECT 'AppointmentServices',COUNT(*) FROM dbo.AppointmentServices
UNION ALL SELECT 'Diagnostics',COUNT(*) FROM dbo.Diagnostics
UNION ALL SELECT 'TreatmentPlans',COUNT(*) FROM dbo.TreatmentPlans
UNION ALL SELECT 'Invoices',COUNT(*) FROM dbo.Invoices;
END TRY
BEGIN CATCH
  IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
  THROW;
END CATCH;
